using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace KAONOMI.Chat.Models;

/// <summary>
/// The JSON report written by KAONOMI.ImmuneSystem (the images generated by AI and the code in Office files found on
/// the machine), as read by /immune. Kept apart from the scanner, which stays a self-contained console application.
/// </summary>
public sealed class ImmuneReport
{
    public string Tool { get; set; } = "";
    public string Version { get; set; } = "";
    public string Machine { get; set; } = "";
    public string User { get; set; } = "";
    public string Os { get; set; } = "";
    public DateTime StartedAt { get; set; }
    public DateTime FinishedAt { get; set; }
    public double DurationSeconds { get; set; }
    public bool Interrupted { get; set; }
    public List<string> Roots { get; set; } = [];
    public ImmuneStats Stats { get; set; } = new();
    public List<ImmuneImage> AiImages { get; set; } = [];
    public List<ImmuneOfficeFile> OfficeFiles { get; set; } = [];
    public List<ImmuneError> Errors { get; set; } = [];

    /// <summary>What the browser histories say (null when they were not read).</summary>
    public ImmuneBrowsers? Browsers { get; set; }

    /// <summary>The file the report was read from.</summary>
    [JsonIgnore]
    public string File { get; set; } = "";

    public static readonly JsonSerializerOptions Json = new() { PropertyNameCaseInsensitive = true };
}

public sealed class ImmuneStats
{
    public long Directories { get; set; }
    public long Files { get; set; }
    public long ImagesInspected { get; set; }
    public long OfficeFilesInspected { get; set; }
    public long SkippedTooLarge { get; set; }
    public long Errors { get; set; }
    public long AiImages { get; set; }
    public long OfficeFilesWithCode { get; set; }
    public long BrowserProfiles { get; set; }
    public long AiServices { get; set; }
}

public sealed class ImmuneImage
{
    public string Path { get; set; } = "";
    public long Size { get; set; }
    public DateTime Modified { get; set; }
    public string Format { get; set; } = "";

    /// <summary><c>ai-generated</c> or <c>ai-edited</c>.</summary>
    public string Kind { get; set; } = "";

    /// <summary><c>low</c>, <c>medium</c> or <c>high</c>.</summary>
    public string Confidence { get; set; } = "";

    public string? Generator { get; set; }
    public bool ContentCredentials { get; set; }
    public string? Prompt { get; set; }
    public List<ImmuneEvidence> Evidence { get; set; } = [];

    /// <summary>Where it was downloaded from.</summary>
    public string? Origin { get; set; }

    [JsonIgnore]
    public string Name => System.IO.Path.GetFileName(Path);
}

public sealed class ImmuneEvidence
{
    public string Source { get; set; } = "";
    public string Detail { get; set; } = "";
    public string Confidence { get; set; } = "";
}

public sealed class ImmuneOfficeFile
{
    public string Path { get; set; } = "";
    public long Size { get; set; }
    public DateTime Modified { get; set; }
    public string Format { get; set; } = "";
    public string Container { get; set; } = "";

    /// <summary><c>info</c>, <c>low</c>, <c>medium</c> or <c>high</c>.</summary>
    public string Severity { get; set; } = "";

    public List<ImmuneFinding> Findings { get; set; } = [];

    /// <summary>Where it was downloaded from.</summary>
    public string? Origin { get; set; }

    [JsonIgnore]
    public string Name => System.IO.Path.GetFileName(Path);
}

public sealed class ImmuneFinding
{
    public string Kind { get; set; } = "";
    public string Severity { get; set; } = "";
    public string Location { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string>? AutoExec { get; set; }
    public List<string>? Suspicious { get; set; }
    public List<string>? Iocs { get; set; }
    public int? Lines { get; set; }
    public string? Code { get; set; }
}

public sealed class ImmuneError
{
    public string Path { get; set; } = "";
    public string Error { get; set; } = "";
}

/// <summary>The browser histories: the profiles read, the AI services visited, the images and Office files downloaded.</summary>
public sealed class ImmuneBrowsers
{
    public List<ImmuneBrowserProfile> Profiles { get; set; } = [];
    public List<ImmuneAiService> AiServices { get; set; } = [];
    public List<ImmuneDownload> Downloads { get; set; } = [];
    public long Visits { get; set; }
    public long AiVisits { get; set; }
    public DateTime? From { get; set; }
    public DateTime? To { get; set; }
}

public sealed class ImmuneBrowserProfile
{
    public string Browser { get; set; } = "";
    public string Profile { get; set; } = "";
    public string Path { get; set; } = "";
    public bool Readable { get; set; }
    public string? Error { get; set; }
    public long Visits { get; set; }
    public long AiVisits { get; set; }
    public DateTime? From { get; set; }
    public DateTime? To { get; set; }
}

public sealed class ImmuneAiService
{
    public string Name { get; set; } = "";

    /// <summary><c>chat</c>, <c>image</c>, <c>video</c>, <c>audio</c>, <c>code</c> or <c>writing</c>.</summary>
    public string Category { get; set; } = "";

    public long Visits { get; set; }
    public DateTime FirstVisit { get; set; }
    public DateTime LastVisit { get; set; }
    public List<string> Browsers { get; set; } = [];

    /// <summary>Visits per month (<c>yyyy-MM</c>).</summary>
    public Dictionary<string, long> Months { get; set; } = [];
}

public sealed class ImmuneDownload
{
    public string Browser { get; set; } = "";
    public string Profile { get; set; } = "";
    public string File { get; set; } = "";

    /// <summary><c>image</c> or <c>office</c>.</summary>
    public string Kind { get; set; } = "";

    public string? Source { get; set; }
    public string? Referrer { get; set; }
    public DateTime? Time { get; set; }
    public long? Size { get; set; }
    public bool Exists { get; set; }
    public string? Service { get; set; }

    /// <summary><c>ai-image</c> or <c>office-code</c> when the scan found something in it.</summary>
    public string? Finding { get; set; }

    [JsonIgnore]
    public string Name => System.IO.Path.GetFileName(File);
}
